// Purges legacy auto-generated Crew / Cast / Vendor rows for a given project.
// Called before applying a fresh budget import so nothing that was auto-created
// from a previous "NAME" column parse can linger.
import { createServerFn } from "@tanstack/react-start";
import { z } from "zod";
import { requireSupabaseAuth } from "@/integrations/supabase/auth-middleware";

const Input = z.object({ projectId: z.string().uuid() });

export const purgeAutoGeneratedForProject = createServerFn({ method: "POST" })
  .middleware([requireSupabaseAuth])
  .inputValidator((input: unknown) => Input.parse(input))
  .handler(async ({ data, context }) => {
    const { supabase } = context;
    const { projectId } = data;

    const [crew, people, vendors] = await Promise.all([
      supabase
        .from("crew_members")
        .delete()
        .eq("project_id", projectId)
        .eq("is_auto_generated", true),
      supabase.from("people").delete().eq("project_id", projectId).eq("is_auto_generated", true),
      supabase.from("vendors").delete().eq("project_id", projectId).eq("is_auto_generated", true),
    ]);

    return {
      crewPurged: crew.error ? 0 : (crew.count ?? 0),
      peoplePurged: people.error ? 0 : (people.count ?? 0),
      vendorsPurged: vendors.error ? 0 : (vendors.count ?? 0),
      errors: [crew.error, people.error, vendors.error].filter(Boolean).map((e) => e!.message),
    };
  });
